<script setup lang="ts">
import{brand}from'./brand';import{computed,onMounted,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{state,isAdmin,initialize,logout}from'./store';import{run}from'./api';import Icon from './components/Icon.vue'
const route=useRoute(),router=useRouter(),mobile=ref(false),notifications=ref(false),search=ref('')
const menu=[{path:'/',label:'俱乐部首页',icon:'dashboard'},{path:'/clubs',label:'俱乐部展示',icon:'compass'},{path:'/activities',label:'骑行活动',icon:'calendar'},{path:'/suggestions',label:'活动建议',icon:'calendar'},{path:'/center',label:'成员中心',icon:'user'}]
const notes=computed(()=>[...state.mine.memberships.map(x=>({title:x.club.name+' · 入社申请',text:x.reviewNote||'可在成员中心查看审核状态'})),...state.mine.loans.map(x=>({title:x.equipment.name+' · 器材借用',text:x.reviewNote||'可在成员中心查看借还进度'})),...state.mine.repairs.map(x=>({title:x.title,text:x.updates.at(-1)?.note||'工单已提交'}))].slice(0,12))
const today=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date())
function submitSearch(){router.push({path:'/clubs',query:{q:search.value.trim()}});search.value=''}
watch(()=>route.fullPath,()=>mobile.value=false)
onMounted(async()=>{await initialize();if((route.meta.auth||route.meta.admin)&&!state.user)router.replace({path:'/login',query:{redirect:route.fullPath}});else if(route.meta.admin&&!isAdmin.value)router.replace('/')})
</script>
<template>
 <div class="app-shell"><div v-if="mobile" class="sidebar-shade" @click="mobile=false"/>
 <aside class="sidebar" :class="{open:mobile}"><router-link to="/" class="brand" :aria-label="brand.fullName"><span class="brand-mark"><Icon name="bike" :size="29"/></span><span class="brand-title">{{brand.name}}<small>{{brand.school}}</small></span></router-link><button class="mobile-close icon-button" aria-label="关闭导航" @click="mobile=false"><Icon name="x"/></button>
 <div class="sidebar-caption">我的征途 <span>俱乐部空间</span></div><nav><router-link v-for="item in menu" :key="item.path" :to="item.path" class="nav-link" :class="{active:route.path===item.path}"><Icon :name="item.icon"/><span>{{item.label}}</span><span v-if="item.path==='/activities'" class="nav-count">{{state.overview.upcomingCount||0}}</span></router-link></nav>
 <div class="sidebar-caption tools-caption">骑行服务 <span>器材保障</span></div><nav><router-link to="/rooms" class="nav-link" :class="{active:route.path==='/rooms'}"><Icon name="bike"/><span>骑行室使用</span></router-link><router-link to="/equipment" class="nav-link" :class="{active:route.path==='/equipment'}"><Icon name="package"/><span>器材借用</span></router-link><router-link to="/repairs" class="nav-link" :class="{active:route.path==='/repairs'}"><Icon name="wrench"/><span>在线报修</span></router-link><router-link v-if="isAdmin" to="/admin" class="nav-link" :class="{active:route.path==='/admin'}"><Icon name="shield"/><span>管理工作台</span></router-link></nav>
 <div class="sidebar-bottom"><div class="sidebar-note"><span class="note-leaf"><Icon name="leaf" :size="25"/></span><h4>热爱不设终点</h4><p>和志同道合的骑友，<br>一起骑向下一段征途。</p><router-link to="/clubs">了解征途 · 申请加入 <Icon name="arrow" :size="15"/></router-link></div><div class="sidebar-footer"><span class="system-dot"/>征途单车 · 与你同行 <span>v1.0</span></div></div></aside>
 <div class="workspace"><header class="topbar"><div class="topbar-left"><button class="mobile-menu icon-button" aria-label="打开导航" @click="mobile=true"><Icon name="menu"/></button><span class="breadcrumb-root">工作空间</span><Icon name="right" :size="14"/><strong>{{route.meta.title}}</strong></div><div class="topbar-actions"><form class="global-search" @submit.prevent="submitSearch"><Icon name="search" :size="17"/><input v-model="search" placeholder="搜索俱乐部与社团…" aria-label="搜索社团"><kbd>↵</kbd></form><button class="icon-button bell-button" aria-label="查看消息" @click="notifications=true"><Icon name="bell"/><i v-if="notes.length"/></button><span class="topbar-divider"/><router-link v-if="state.user" to="/center" class="profile-link"><span class="avatar">{{state.user.name[0]}}</span><span><b>{{state.user.name}}</b><small>{{state.user.role==='SUPER_ADMIN'?'超级管理员':isAdmin?'俱乐部管理员':'征途骑友'}}</small></span><Icon name="down" :size="14"/></router-link><router-link v-else to="/login" class="login-link">登录 / 注册<Icon name="arrow" :size="15"/></router-link></div></header>
 <main><div v-if="!state.ready" class="loading-page"><el-skeleton :rows="12" animated/></div><div v-else-if="state.error" class="panel error-panel"><Icon name="alert" :size="38"/><h2>暂时无法连接俱乐部</h2><p>{{state.error}}</p><el-button type="primary" @click="initialize">重新连接</el-button></div><router-view v-else/></main><footer class="page-footer"><span>© {{new Date().getFullYear()}} {{brand.fullName}} · 安全同行，热爱骑行</span><span>{{today}}</span></footer></div></div>
 <el-drawer v-model="notifications" title="我的消息" size="min(400px, 100vw)"><div v-if="!state.user" class="empty-block"><Icon name="bell" :size="36"/><h3>登录后查看你的动态</h3><el-button type="primary" @click="notifications=false;router.push('/login')">去登录</el-button></div><template v-else><p class="muted">来自你的申请、借用与报修记录</p><div v-for="(n,i) in notes" :key="i" class="notification"><span class="notification-dot"/><div><h4>{{n.title}}</h4><p>{{n.text}}</p></div></div><el-empty v-if="!notes.length" description="暂时没有新的动态"/><el-button class="full-width" @click="notifications=false;router.push('/center')">查看成员中心</el-button><el-button class="full-width logout-button" @click="run(async()=>{await logout();notifications=false;router.push('/')},'已安全退出')">退出当前账号</el-button></template></el-drawer>
</template>

<style>.brand .brand-title{font-size:14px;line-height:1.5;white-space:normal}.brand .brand-title small{font-size:10px}.member-identity-panel{padding:22px 26px;margin-top:20px;display:flex;align-items:center;gap:14px;flex-wrap:wrap}.member-identity-panel p{font-size:12px;line-height:1.9;flex-basis:100%;color:#7c8b70}.center-stats.stats-grid{grid-template-columns:repeat(3,minmax(0,1fr))}@media(max-width:680px){.center-stats.stats-grid{grid-template-columns:1fr}.member-identity-panel{padding:20px}.member-identity-panel strong{font-size:14px}}</style>
